widget.solution:
import numpy as np

def spurious_rate(n, sims, seed0, crit=1.96):
    hits = 0
    for seed in range(seed0, seed0 + sims):
        x, y = make_two_walks(seed, n)
        r = np.corrcoef(x, y)[0, 1]
        t = abs(r) * np.sqrt((n - 2) / (1 - r ** 2))
        hits += t > crit
    return round(hits / sims, 3)
